#!/usr/bin/env python3"""Скрипт для проверки данных пользователя в базе данных"""import sysimport os# Добавляем родительскую директорию в путь Pythonparent_dir = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))sys.path.insert(0, parent_dir)from core.database import enginefrom models.user import Userfrom sqlmodel import Session, selectdef check_user_data():    """Проверяет данные пользователя в базе данных"""    with Session(engine) as session:        # Находим пользователя ivan        user = session.exec(select(User).where(User.username == "ivan")).first()                if user:            print(f"Пользователь найден: {user.username} (ID: {user.id})")            print(f"Email: {user.email}")            print(f"Subscription tier: {user.subscription_tier}")            print(f"Messages used: {user.messages_used}")            print(f"Messages limit: {user.messages_limit}")            print(f"API access: {user.api_access}")            print(f"Created at: {user.created_at}")            print(f"Updated at: {user.updated_at}")                        # Проверяем все сообщения пользователя            from models.conversation import Conversation            from models.message import Message                        conversations = session.exec(select(Conversation).where(Conversation.user_id == user.id)).all()            print(f"\nКоличество разговоров: {len(conversations)}")                        total_messages = 0            for conv in conversations:                messages = session.exec(select(Message).where(Message.conversation_id == conv.id)).all()                user_messages = [m for m in messages if m.is_from_user]                total_messages += len(user_messages)                print(f"Разговор {conv.id}: {len(user_messages)} сообщений от пользователя")                        print(f"\nОбщее количество сообщений от пользователя: {total_messages}")            print(f"Messages used в БД: {user.messages_used}")                        if total_messages != user.messages_used:                print(f"PROBLEM: Messages used in DB ({user.messages_used}) does not match real count ({total_messages})")                                # Обновляем messages_used                user.messages_used = total_messages                session.add(user)                session.commit()                print(f"UPDATED: messages_used set to {total_messages}")            else:                print("OK: Message count matches")                        else:            print("Пользователь 'ivan' не найден")if __name__ == "__main__":    check_user_data()